import chess

MOTIF_NAME = 'Healthy mobile wing majority'
MOTIF_DESCRIPTION = 'With balanced non-pawn forces and no advanced passer, the side to move has a healthier connected wing majority than the opponent’s best countermajority.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    if board.is_check():
        return False
    if len(board.pieces(chess.QUEEN, stm)) != len(board.pieces(chess.QUEEN, opp)):
        return False
    if len(board.pieces(chess.ROOK, stm)) != len(board.pieces(chess.ROOK, opp)):
        return False
    if (len(board.pieces(chess.BISHOP, stm)) + len(board.pieces(chess.KNIGHT, stm)) !=
            len(board.pieces(chess.BISHOP, opp)) + len(board.pieces(chess.KNIGHT, opp))):
        return False

    pawns = {
        stm: set(board.pieces(chess.PAWN, stm)),
        opp: set(board.pieces(chess.PAWN, opp)),
    }
    if len(pawns[stm]) - len(pawns[opp]) not in (0, 1):
        return False

    def progress(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def passed(sq, color):
        f, r = chess.square_file(sq), chess.square_rank(sq)
        for enemy in pawns[not color]:
            ef, er = chess.square_file(enemy), chess.square_rank(enemy)
            if abs(ef - f) <= 1:
                if color == chess.WHITE and er > r:
                    return False
                if color == chess.BLACK and er < r:
                    return False
        return True

    for color in (stm, opp):
        if any(progress(sq, color) >= 4 and passed(sq, color) for sq in pawns[color]):
            return False

    def defects(color):
        counts = [sum(chess.square_file(sq) == f for sq in pawns[color]) for f in range(8)]
        doubled = sum(max(0, n - 1) for n in counts)
        isolated = sum(
            not ((f > 0 and counts[f - 1]) or (f < 7 and counts[f + 1]))
            for f in (chess.square_file(sq) for sq in pawns[color])
        )
        return 2 * doubled + isolated

    def wing_score(color, files):
        own = [sq for sq in pawns[color] if chess.square_file(sq) in files]
        enemy = [sq for sq in pawns[not color] if chess.square_file(sq) in files]
        if len(own) < 2 or len(own) <= len(enemy):
            return -100
        if any(sum(chess.square_file(sq) == f for sq in own) > 1 for f in files):
            return -100

        connected = 0
        mobile = 0
        protected = 0
        unsafe = 0
        advance = 0
        direction = 1 if color == chess.WHITE else -1

        for sq in own:
            f, r = chess.square_file(sq), chess.square_rank(sq)
            if any(abs(chess.square_file(other) - f) == 1 and
                   abs(chess.square_rank(other) - r) <= 1 for other in own):
                connected += 1
            nr = r + direction
            if 0 <= nr < 8 and board.piece_at(chess.square(f, nr)) is None:
                mobile += 1
            defended = any(a in pawns[color] for a in board.attackers(color, sq))
            pawn_attacked = any(a in pawns[not color] for a in board.attackers(not color, sq))
            if defended:
                protected += 1
            if pawn_attacked and not board.attackers(color, sq):
                unsafe += 1
            advance += max(0, progress(sq, color) - 1)

        if connected < 2 or mobile == 0 or unsafe > 1:
            return -100
        return (4 * (len(own) - len(enemy)) + connected + mobile +
                protected + advance - 3 * unsafe - defects(color))

    own_best = max(wing_score(stm, (0, 1, 2)), wing_score(stm, (5, 6, 7)))
    enemy_best = max(wing_score(opp, (0, 1, 2)), wing_score(opp, (5, 6, 7)))
    return bool(own_best > -100 and own_best >= enemy_best + 3)

import chess

MOTIF_NAME = 'Level-material mobility dominance'
MOTIF_DESCRIPTION = 'With material values level, the side to move has substantially greater effective mobility for its non-pawn pieces.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
              chess.ROOK: 5, chess.QUEEN: 9}

    def material(color):
        return sum(values[p] * len(board.pieces(p, color)) for p in values)

    def mobility(color):
        total = 0
        for p in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(p, color):
                for target in board.attacks(sq):
                    occupant = board.piece_at(target)
                    if occupant is None or occupant.color != color:
                        total += 1
        return total

    return (not board.is_check() and material(stm) == material(opp)
            and mobility(stm) >= mobility(opp) + 8)

import chess

MOTIF_NAME = 'Safe forcing check against an exposed central king'
MOTIF_DESCRIPTION = 'With material roughly level, the side to move can give a non-sacrificial forcing check to an exposed king on the central files.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm, opp = board.turn, not board.turn
    values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
              chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 20}

    def material(color):
        return sum(values[t] * len(board.pieces(t, color))
                   for t in range(chess.PAWN, chess.QUEEN + 1))

    if abs(material(stm) - material(opp)) > 1:
        return False

    king = board.king(opp)
    if king is None or not 2 <= chess.square_file(king) <= 5:
        return False
    kr, kf = chess.square_rank(king), chess.square_file(king)
    home = 0 if opp else 7
    front = kr + (1 if opp else -1)
    shelter = 0
    if 0 <= front < 8:
        for f in range(max(0, kf - 1), min(8, kf + 2)):
            p = board.piece_at(chess.square(f, front))
            shelter += bool(p and p.color == opp and p.piece_type == chess.PAWN)
    if kr == home and shelter >= 3:
        return False

    for move in list(board.legal_moves):
        if not board.gives_check(move):
            continue
        mover = board.piece_at(move.from_square)
        captured = board.piece_at(move.to_square)
        gain = values[captured.piece_type] if captured else (
            1 if board.is_en_passant(move) else 0
        )
        mover_type = mover.piece_type
        board.push(move)
        replies = list(board.legal_moves)
        enemy_king = board.king(opp)
        vulnerable = {move.to_square}
        if enemy_king is not None:
            vulnerable |= set(board.attackers(stm, enemy_king))

        safe = True
        for reply in replies:
            if not board.is_capture(reply) or reply.to_square not in vulnerable:
                continue
            lost = board.piece_at(reply.to_square)
            capturer = board.piece_at(reply.from_square)
            if lost is None:
                continue
            lost_value = values[lost.piece_type]
            capturer_value = values[capturer.piece_type]
            board.push(reply)
            recapture = any(
                board.is_capture(answer) and answer.to_square == reply.to_square
                for answer in board.legal_moves
            )
            board.pop()
            if gain < lost_value and (
                not recapture or gain + capturer_value < lost_value
            ):
                safe = False
                break

        forcing = (len(replies) <= 4 or gain > 0 or
                   mover_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP))
        board.pop()
        if safe and forcing:
            return True
    return False

import chess

MOTIF_NAME = 'Unopposed bishop pair at nominal parity'
MOTIF_DESCRIPTION = 'At equal conventional material with matched minor-piece counts, the side to move has bishops on both color complexes while the opponent does not.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
              chess.ROOK: 5, chess.QUEEN: 9}

    def material(color):
        return sum(values[p] * len(board.pieces(p, color)) for p in values)

    if material(stm) != material(opp):
        return False
    if (len(board.pieces(chess.BISHOP, stm)) +
            len(board.pieces(chess.KNIGHT, stm)) !=
            len(board.pieces(chess.BISHOP, opp)) +
            len(board.pieces(chess.KNIGHT, opp))):
        return False

    def bishop_pair(color):
        colors = {(chess.square_file(sq) + chess.square_rank(sq)) & 1
                  for sq in board.pieces(chess.BISHOP, color)}
        return len(colors) == 2

    return bishop_pair(stm) and not bishop_pair(opp)

import chess

MOTIF_NAME = 'Durable material-reversing capture'
MOTIF_DESCRIPTION = 'With no nominal material edge and differing force inventories, the side to move can capture into a material lead that survives every immediate countercapture.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    values = (0, 1, 3, 3, 5, 9, 0)

    def balance():
        return sum(
            values[pt] * (
                len(board.pieces(pt, stm)) - len(board.pieces(pt, opp))
            )
            for pt in range(1, 6)
        )

    before = balance()
    if before > 0:
        return False
    if before == 0 and all(
        len(board.pieces(pt, stm)) == len(board.pieces(pt, opp))
        for pt in range(1, 6)
    ):
        return False

    for move in list(board.legal_moves):
        target = board.piece_at(move.to_square)
        if target is None or target.color != opp:
            continue
        board.push(move)
        if balance() <= 0:
            board.pop()
            continue

        durable = True
        for reply in list(board.legal_moves):
            is_capture = board.is_capture(reply)
            reply_square = reply.to_square
            board.push(reply)
            bad = board.is_checkmate()

            if is_capture and not bad and balance() <= 0:
                restored = False
                for answer in list(board.legal_moves):
                    if board.is_capture(answer) and answer.to_square == reply_square:
                        board.push(answer)
                        restored = balance() > 0
                        board.pop()
                        if restored:
                            break
                bad = not restored

            board.pop()
            if bad:
                durable = False
                break

        board.pop()
        if durable:
            return True
    return False

import chess

MOTIF_NAME = 'Matched-force positional coordination'
MOTIF_DESCRIPTION = 'With matched non-pawn forces and at most a one-pawn investment, the side to move has a pronounced combined edge in space, piece placement, and king security.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm, opp = board.turn, not board.turn

    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        if len(board.pieces(pt, stm)) != len(board.pieces(pt, opp)):
            return False

    ps = len(board.pieces(chess.PAWN, stm))
    po = len(board.pieces(chess.PAWN, opp))
    if ps > po or po - ps > 1 or board.is_check():
        return False

    centers = (chess.D4, chess.E4, chess.D5, chess.E5)

    def placement(color):
        enemy = not color
        pawns = list(board.pieces(chess.PAWN, color))
        enemy_pawns = list(board.pieces(chess.PAWN, enemy))
        files = [sum(chess.square_file(sq) == f for sq in pawns) for f in range(8)]
        enemy_files = [sum(chess.square_file(sq) == f for sq in enemy_pawns) for f in range(8)]
        occupied_files = [f for f in range(8) if files[f]]
        islands = sum(i == 0 or occupied_files[i] > occupied_files[i - 1] + 1
                      for i in range(len(occupied_files)))
        score = -3 * islands - 6 * sum(max(0, n - 1) for n in files)

        for sq in pawns:
            f, r = chess.square_file(sq), chess.square_rank(sq)
            rr = r if color else 7 - r
            score += 2 * max(0, rr - 1)

            if 2 <= f <= 5 and rr >= 3:
                score += 6 + 2 * (rr - 3)
                if f in (3, 4):
                    score += 3

            protected = any(
                board.piece_type_at(a) == chess.PAWN
                for a in board.attackers(color, sq)
            )
            if protected:
                score += 3
            if not any(files[g] for g in (f - 1, f + 1) if 0 <= g < 8):
                score -= 5

            passed = not any(
                abs(chess.square_file(ep) - f) <= 1
                and ((color and chess.square_rank(ep) > r)
                     or (not color and chess.square_rank(ep) < r))
                for ep in enemy_pawns
            )
            if passed:
                score += 6 + 5 * max(0, rr - 2) + (5 if protected else 0)

        for i, a in enumerate(pawns):
            fa, ra = chess.square_file(a), chess.square_rank(a)
            rra = ra if color else 7 - ra
            for b in pawns[i + 1:]:
                fb, rb = chess.square_file(b), chess.square_rank(b)
                rrb = rb if color else 7 - rb
                if abs(fa - fb) == 1 and abs(ra - rb) <= 1 and min(rra, rrb) >= 3:
                    score += 6

        home_n = {chess.B1, chess.G1} if color else {chess.B8, chess.G8}
        home_b = {chess.C1, chess.F1} if color else {chess.C8, chess.F8}

        for sq in board.pieces(chess.KNIGHT, color):
            f, r = chess.square_file(sq), chess.square_rank(sq)
            rr = r if color else 7 - r
            d = min(chess.square_distance(sq, c) for c in centers)
            score += 18 - 10 * d + 2 * max(0, rr - 1)
            supported = any(
                board.piece_type_at(a) == chess.PAWN
                for a in board.attackers(color, sq)
            )
            if supported:
                score += 6
            challenge = any(
                abs(chess.square_file(ep) - f) == 1
                and ((color and chess.square_rank(ep) > r)
                     or (not color and chess.square_rank(ep) < r))
                for ep in enemy_pawns
            )
            if rr >= 3 and 1 <= f <= 6 and supported and not challenge:
                score += 14
            if sq in home_n:
                score -= 7

        for sq in board.pieces(chess.BISHOP, color):
            mobility = sum(
                board.piece_at(t) is None or board.piece_at(t).color != color
                for t in board.attacks(sq)
            )
            score += min(mobility, 10)
            same_color_pawns = sum(
                (chess.square_file(p) + chess.square_rank(p)) % 2
                == (chess.square_file(sq) + chess.square_rank(sq)) % 2
                for p in pawns
            )
            score -= max(0, same_color_pawns - 4)
            if sq in home_b:
                score -= 7

        rooks = list(board.pieces(chess.ROOK, color))
        for sq in rooks:
            f, r = chess.square_file(sq), chess.square_rank(sq)
            rr = r if color else 7 - r
            if not files[f]:
                score += 7
                if not enemy_files[f]:
                    score += 7
            if rr == 6:
                score += 18
            elif rr >= 5:
                score += 8
            score += sum(
                board.piece_at(t) is not None
                and board.piece_at(t).color == enemy
                and board.piece_type_at(t) == chess.PAWN
                for t in board.attacks(sq)
            )

        if len(rooks) > 1 and any(
            b in board.attacks(a) for a in rooks for b in rooks if a != b
        ):
            score += 8

        king = board.king(color)
        if king is not None and board.pieces(chess.QUEEN, enemy):
            kf, kr = chess.square_file(king), chess.square_rank(king)
            score += 6 if kf <= 2 or kf >= 5 else -8
            step = 1 if color else -1
            for df in (-1, 0, 1):
                f = kf + df
                if not 0 <= f < 8:
                    continue
                one, two = kr + step, kr + 2 * step
                if 0 <= one < 8 and board.piece_at(chess.square(f, one)) == chess.Piece(chess.PAWN, color):
                    score += 6
                elif 0 <= two < 8 and board.piece_at(chess.square(f, two)) == chess.Piece(chess.PAWN, color):
                    score += 3
                else:
                    score -= 3
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    f, r = kf + df, kr + dr
                    if 0 <= f < 8 and 0 <= r < 8:
                        score -= 2 * min(2, len(board.attackers(enemy, chess.square(f, r))))

        pin_bonus = {chess.KNIGHT: 10, chess.BISHOP: 10, chess.ROOK: 14, chess.QUEEN: 18}
        for pt, bonus in pin_bonus.items():
            score += bonus * sum(board.is_pinned(enemy, sq) for sq in board.pieces(pt, enemy))

        return score

    return placement(stm) - placement(opp) >= 48 + 12 * (po - ps)

import chess

MOTIF_NAME = 'Targetable pawn-structure superiority'
MOTIF_DESCRIPTION = 'With identical material inventories, the side to move has substantially fewer isolated, doubled, backward, and loose pawns than the opponent.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    if board.is_check():
        return False

    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        if len(board.pieces(pt, stm)) != len(board.pieces(pt, opp)):
            return False

    def pawn_burden(color):
        pawns = list(board.pieces(chess.PAWN, color))
        files = [[] for _ in range(8)]
        for sq in pawns:
            files[chess.square_file(sq)].append(chess.square_rank(sq))

        occupied = [bool(ranks) for ranks in files]
        islands = 0
        for f in range(8):
            if occupied[f] and (f == 0 or not occupied[f - 1]):
                islands += 1

        isolated = sum(
            len(files[f])
            for f in range(8)
            if occupied[f]
            and not (f > 0 and occupied[f - 1])
            and not (f < 7 and occupied[f + 1])
        )
        doubled = sum(max(0, len(ranks) - 1) for ranks in files)
        loose = 0
        backward = 0

        for sq in pawns:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            defended = any(
                board.piece_at(a) is not None
                and board.piece_at(a).piece_type == chess.PAWN
                for a in board.attackers(color, sq)
            )
            pawn_attacked = any(
                board.piece_at(a) is not None
                and board.piece_at(a).piece_type == chess.PAWN
                for a in board.attackers(not color, sq)
            )
            if pawn_attacked and not defended:
                loose += 1

            nr = r + (1 if color else -1)
            if not 0 <= nr < 8 or defended:
                continue
            front = chess.square(f, nr)
            front_controlled = any(
                board.piece_at(a) is not None
                and board.piece_at(a).piece_type == chess.PAWN
                for a in board.attackers(not color, front)
            )
            if not front_controlled:
                continue

            neighbor_ranks = []
            if f > 0:
                neighbor_ranks += files[f - 1]
            if f < 7:
                neighbor_ranks += files[f + 1]
            can_support = any(
                rr <= r if color else rr >= r
                for rr in neighbor_ranks
            )
            if not can_support:
                backward += 1

        return (
            2 * isolated
            + 2 * doubled
            + max(0, islands - 1)
            + loose
            + backward
        )

    own = pawn_burden(stm)
    enemy = pawn_burden(opp)
    threshold = 4 if not board.pieces(chess.QUEEN, stm) else 5
    return enemy >= 5 and enemy - own >= threshold

import chess

MOTIF_NAME = 'Wing-king pressure superiority at material parity'
MOTIF_DESCRIPTION = 'At equal material with queens and both kings on the wings, the side to move has concentrated pressure around the opposing king that clearly exceeds the opponent’s attack and pawn-cover safety.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm, opp = board.turn, not board.turn
    values = {
        chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
        chess.ROOK: 5, chess.QUEEN: 9
    }

    def material(color):
        return sum(v * len(board.pieces(pt, color)) for pt, v in values.items())

    if material(stm) != material(opp):
        return False
    if not board.pieces(chess.QUEEN, stm) or not board.pieces(chess.QUEEN, opp):
        return False

    own_king, enemy_king = board.king(stm), board.king(opp)
    if own_king is None or enemy_king is None:
        return False
    if chess.square_file(own_king) in (3, 4) or chess.square_file(enemy_king) in (3, 4):
        return False

    weights = {
        chess.PAWN: 1, chess.KNIGHT: 2, chess.BISHOP: 2,
        chess.ROOK: 3, chess.QUEEN: 4
    }

    def pressure(color, king):
        score = 0
        for pt, weight in weights.items():
            for sq in board.pieces(pt, color):
                near = 3
                for target in board.attacks(sq):
                    near = min(near, chess.square_distance(target, king))
                if near <= 2:
                    score += weight
                    if near <= 1:
                        score += 2
        return score

    def shelter_holes(color, king):
        f = chess.square_file(king)
        files = range(max(0, f - 1), min(7, f + 1) + 1)
        ranks = (1, 2) if color == chess.WHITE else (6, 5)
        pawns = board.pieces(chess.PAWN, color)
        return sum(not any(chess.square(ff, r) in pawns for r in ranks) for ff in files)

    attack = pressure(stm, enemy_king)
    counter = pressure(opp, own_king)
    attack_danger = attack + 2 * shelter_holes(opp, enemy_king)
    counter_danger = counter + 2 * shelter_holes(stm, own_king)
    return bool(attack >= 7 and attack_danger >= counter_danger + 4)

import chess

MOTIF_NAME = 'Queen-led multi-piece king-zone encirclement'
MOTIF_DESCRIPTION = 'At near material parity, the side to move has a coordinated queen-led attack around the opposing king that substantially exceeds the counterattack.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check() or board.king(stm) is None or board.king(opp) is None:
        return False

    values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
              chess.ROOK: 5, chess.QUEEN: 9}
    own_material = sum(values[p] * len(board.pieces(p, stm)) for p in values)
    opp_material = sum(values[p] * len(board.pieces(p, opp)) for p in values)
    if not -2 <= own_material - opp_material <= 2:
        return False
    if not board.pieces(chess.QUEEN, stm):
        return False

    for sq in board.pieces(chess.PAWN, opp):
        rel = chess.square_rank(sq) + 1 if opp else 8 - chess.square_rank(sq)
        if rel >= 7:
            return False

    def attack_data(color):
        enemy = not color
        king = board.king(enemy)
        kf = chess.square_file(king)
        kr = chess.square_rank(king)
        forward = 1 if enemy else -1
        zone = set()
        for df in range(-2, 3):
            f = kf + df
            if 0 <= f < 8:
                for step in (0, 1, 2):
                    r = kr + step * forward
                    if 0 <= r < 8:
                        zone.add(chess.square(f, r))

        score = 0
        participants = 0
        queen_joined = 0
        covered = set()
        base = {chess.PAWN: 1, chess.KNIGHT: 4, chess.BISHOP: 4,
                chess.ROOK: 5, chess.QUEEN: 7}
        for piece_type in base:
            for sq in board.pieces(piece_type, color):
                if board.is_pinned(color, sq):
                    continue
                hits = set(board.attacks(sq)) & zone
                if not hits:
                    continue
                covered.update(hits)
                score += base[piece_type] + 2 * len(hits)
                if chess.square_distance(sq, king) <= 3:
                    score += 2
                if piece_type != chess.PAWN:
                    participants += 1
                if piece_type == chess.QUEEN:
                    queen_joined = 1

        shield = 0
        for df in (-1, 0, 1):
            f = kf + df
            if 0 <= f < 8:
                for step in (1, 2):
                    r = kr + step * forward
                    if 0 <= r < 8:
                        p = board.piece_at(chess.square(f, r))
                        if p and p.color == enemy and p.piece_type == chess.PAWN:
                            shield += 1
                            break
        score += 2 * len(covered) + 2 * max(0, 3 - shield)
        return score * 100 + min(participants, 9) * 10 + queen_joined

    own = attack_data(stm)
    rival = attack_data(opp)
    own_score, rival_score = own // 100, rival // 100
    participants = (own // 10) % 10
    queen_joined = own % 10
    return bool(queen_joined and participants >= 3 and
                own_score >= 32 and own_score >= rival_score + 10)

