MOTIF_NAME = 'Uncontested connected-rook file control'
MOTIF_DESCRIPTION = 'With identical material inventories, the side to move has connected rooks controlling a safe semi-open forward lane while the opposing rooks lack comparable coordination.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    if board.is_check():
        return False
    if any(len(board.pieces(pt, stm)) != len(board.pieces(pt, opp))
           for pt in range(chess.PAWN, chess.QUEEN + 1)):
        return False

    def coordinated_lane(color):
        rooks = list(board.pieces(chess.ROOK, color))
        if len(rooks) < 2:
            return False
        connected = any(
            rooks[j] in board.attacks(rooks[i])
            for i in range(len(rooks))
            for j in range(i + 1, len(rooks))
        )
        if not connected:
            return False

        pawns = board.pieces(chess.PAWN, color)
        step = 8 if color else -8
        for rook in rooks:
            file = chess.square_file(rook)
            if any(chess.square_file(pawn) == file for pawn in pawns):
                continue
            clear = 0
            sq = rook + step
            while 0 <= sq < 64 and chess.square_file(sq) == file:
                if board.piece_at(sq):
                    break
                clear += 1
                sq += step
            if clear < 2:
                continue
            safe = True
            for attacker in board.attackers(not color, rook):
                piece = board.piece_at(attacker)
                if piece and piece.piece_type in (
                    chess.PAWN, chess.KNIGHT, chess.BISHOP
                ) and not board.is_pinned(not color, attacker):
                    safe = False
                    break
            if safe and not any(
                board.piece_at(a).piece_type == chess.ROOK
                for a in board.attackers(not color, rook)
                if board.piece_at(a)
            ):
                return True
        return False

    return bool(coordinated_lane(stm) and not coordinated_lane(opp))

