MOTIF_NAME = 'Productive secure invasion superiority'
MOTIF_DESCRIPTION = 'Without a material edge, the side to move has a clearly superior secure invasion by productive non-pawn pieces in the opponent’s half.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    values = (0, 1, 3, 3, 5, 9, 99)

    own = 0
    enemy = 0
    for piece_type in range(1, 6):
        own += values[piece_type] * len(board.pieces(piece_type, stm))
        enemy += values[piece_type] * len(board.pieces(piece_type, opp))
    if own > enemy or enemy - own > 1:
        return False

    scores = []
    counts = []
    supported = []
    for color in (stm, opp):
        other = not color
        king = board.king(other)
        zone = set()
        if king is not None:
            zone = set(board.attacks(king))
            zone.add(king)
        score = 0
        count = 0
        support_count = 0
        for piece_type in range(chess.KNIGHT, chess.QUEEN + 1):
            for square in board.pieces(piece_type, color):
                rank = chess.square_rank(square)
                advance = rank if color == chess.WHITE else 7 - rank
                if advance < 3 or board.is_pinned(color, square):
                    continue
                attackers = board.attackers(other, square)
                defenders = board.attackers(color, square)
                if attackers:
                    if not defenders:
                        continue
                    least = 99
                    for attacker in attackers:
                        piece = board.piece_at(attacker)
                        if piece is not None and values[piece.piece_type] < least:
                            least = values[piece.piece_type]
                    if least < values[piece_type]:
                        continue
                attacks = set(board.attacks(square))
                productive = len(attacks & zone) >= 2
                if not productive:
                    for target in attacks:
                        piece = board.piece_at(target)
                        if piece is not None and piece.color == other:
                            productive = True
                            break
                if not productive:
                    continue
                count += 1
                if defenders:
                    support_count += 1
                if advance >= 5:
                    score += 3
                elif advance == 4:
                    score += 2
                else:
                    score += 1
        scores.append(score)
        counts.append(count)
        supported.append(support_count)

    if scores[0] < 2 or scores[0] < scores[1] + 2:
        return False
    if counts[0] == 1 and (scores[0] < 3 or supported[0] == 0):
        return False
    return True

