MOTIF_NAME = 'Shelter-asymmetric safe wing check'
MOTIF_DESCRIPTION = 'At near material parity, the side to move has better pawn shelter and a non-sacrificial direct check against a less-sheltered wing king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False

    values = {
        chess.PAWN: 1,
        chess.KNIGHT: 3,
        chess.BISHOP: 3,
        chess.ROOK: 5,
        chess.QUEEN: 9,
    }

    def material(color):
        return sum(values[p] * len(board.pieces(p, color)) for p in values)

    if abs(material(stm) - material(opp)) > 1:
        return False

    sk = board.king(stm)
    ok = board.king(opp)
    if sk is None or ok is None:
        return False

    of = chess.square_file(ok)
    home_distance = chess.square_rank(ok) if opp else 7 - chess.square_rank(ok)
    if home_distance > 2 or 2 < of < 5:
        return False

    def shelter(color, king):
        f, r = chess.square_file(king), chess.square_rank(king)
        direction = 1 if color else -1
        score = 0
        for nf in range(max(0, f - 1), min(7, f + 1) + 1):
            for distance in (1, 2):
                nr = r + direction * distance
                if 0 <= nr < 8:
                    piece = board.piece_at(chess.square(nf, nr))
                    if piece and piece.color == color and piece.piece_type == chess.PAWN:
                        score += 3 - distance
                        break
        return score

    own_shelter = shelter(stm, sk)
    enemy_shelter = shelter(opp, ok)
    if enemy_shelter > 4 or own_shelter < enemy_shelter + 2:
        return False

    kf, kr = chess.square_file(ok), chess.square_rank(ok)

    def direct_check(move, piece_type):
        tf = chess.square_file(move.to_square)
        tr = chess.square_rank(move.to_square)
        df, dr = kf - tf, kr - tr

        if piece_type == chess.KNIGHT:
            return sorted((abs(df), abs(dr))) == [1, 2]
        if piece_type == chess.PAWN:
            return abs(df) == 1 and dr == (1 if stm else -1)
        if piece_type == chess.BISHOP:
            aligned = abs(df) == abs(dr) and df != 0
        elif piece_type == chess.ROOK:
            aligned = (df == 0) != (dr == 0)
        elif piece_type == chess.QUEEN:
            aligned = (abs(df) == abs(dr) and df != 0) or ((df == 0) != (dr == 0))
        else:
            return False
        if not aligned:
            return False

        sf = (df > 0) - (df < 0)
        sr = (dr > 0) - (dr < 0)
        f, r = tf + sf, tr + sr
        while (f, r) != (kf, kr):
            sq = chess.square(f, r)
            if sq != move.from_square and board.piece_at(sq):
                return False
            f += sf
            r += sr
        return True

    for move in board.legal_moves:
        piece = board.piece_at(move.from_square)
        if not piece:
            continue
        moved_type = move.promotion or piece.piece_type
        if not direct_check(move, moved_type):
            continue

        victim = board.piece_at(move.to_square)
        captured_value = values.get(victim.piece_type, 0) if victim and victim.color == opp else 0
        moved_value = values.get(moved_type, 100)
        attackers = set(board.attackers(opp, move.to_square))
        defenders = set(board.attackers(stm, move.to_square))
        defenders.discard(move.from_square)

        if not attackers or captured_value > moved_value:
            return True
        if defenders:
            least_attacker = min(
                values.get(board.piece_at(sq).piece_type, 100)
                for sq in attackers
                if board.piece_at(sq)
            )
            if captured_value + least_attacker >= moved_value:
                return True

    return False

