MOTIF_NAME = 'Clean capture from identical material'
MOTIF_DESCRIPTION = 'With identical material inventories, the side to move can capture a more valuable piece or make a capture that has no immediate legal recapture.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    values = {
        chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3,
        chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100
    }

    for piece_type in range(chess.PAWN, chess.KING):
        if len(board.pieces(piece_type, stm)) != len(board.pieces(piece_type, opp)):
            return False

    for move in list(board.legal_moves):
        if not board.is_capture(move):
            continue
        attacker = board.piece_at(move.from_square)
        captured = board.piece_at(move.to_square)
        captured_value = values[captured.piece_type] if captured else values[chess.PAWN]
        if captured_value > values[attacker.piece_type]:
            return True

        board.push(move)
        recapturable = any(
            reply.to_square == move.to_square and board.is_capture(reply)
            for reply in board.legal_moves
        )
        board.pop()
        if not recapturable:
            return True

    return False

