MOTIF_NAME = 'Protected advanced knight outpost superiority'
MOTIF_DESCRIPTION = 'The side to move has a pawn-supported advanced knight outpost whose activity and stability clearly exceed any opposing knight outpost.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn

    def best_outpost(color):
        enemy = not color
        king = board.king(enemy)
        best = 0
        for sq in board.pieces(chess.KNIGHT, color):
            r, f = chess.square_rank(sq), chess.square_file(sq)
            progress = r if color else 7 - r
            if progress < 4 or not 1 <= f <= 6:
                continue
            if not any(
                board.piece_at(a).piece_type == chess.PAWN
                for a in board.attackers(color, sq)
            ):
                continue
            if any(
                board.piece_at(a).piece_type == chess.PAWN
                for a in board.attackers(enemy, sq)
            ):
                continue

            q = 4 + int(2 <= f <= 5) + int(progress >= 5)
            challengers = any(
                abs(chess.square_file(p) - f) == 1
                and ((color and chess.square_rank(p) > r) or
                     (not color and chess.square_rank(p) < r))
                for p in board.pieces(chess.PAWN, enemy)
            )
            q += 2 * int(not challengers)
            q += min(2, sum(
                1 for t in board.attacks(sq)
                if board.color_at(t) == enemy
                and board.piece_type_at(t) not in (chess.PAWN, chess.KING)
            ))
            if king is not None and chess.square_distance(sq, king) <= 3:
                q += 1
            best = max(best, q)
        return best

    own = best_outpost(stm)
    enemy = best_outpost(not stm)
    return bool(own >= 5 and own >= enemy + 2)

