MOTIF_NAME = 'Pawn-anchored central space domination'
MOTIF_DESCRIPTION = 'At nominal material parity, the side to move has a substantially stronger secure central space complex built around protected advanced pawns.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    values = (0, 1, 3, 3, 5, 9, 0)

    def material(color):
        return sum(values[p.piece_type] for p in board.piece_map().values()
                   if p.color == color)

    if material(stm) != material(not stm):
        return False

    def relative_rank(sq, color):
        r = chess.square_rank(sq)
        return r + 1 if color else 8 - r

    def secure_pawn(sq, color):
        f = chess.square_file(sq)
        rel = relative_rank(sq, color)
        own_pawns = board.pieces(chess.PAWN, color)
        enemy_pawns = board.pieces(chess.PAWN, not color)
        if not (4 <= rel <= 6 and 1 <= f <= 6):
            return False
        if not (board.attackers(color, sq) & own_pawns):
            return False
        if board.attackers(not color, sq) & enemy_pawns:
            return False
        return bool(len(board.attackers(color, sq)) >=
                    len(board.attackers(not color, sq)))

    def has_anchor(color):
        return any(secure_pawn(sq, color)
                   for sq in board.pieces(chess.PAWN, color))

    def space_score(color):
        score = 0
        pawns = board.pieces(chess.PAWN, color)
        enemy_pawns = board.pieces(chess.PAWN, not color)

        for sq in pawns:
            if secure_pawn(sq, color):
                rel = relative_rank(sq, color)
                f = chess.square_file(sq)
                score += 4 + 2 * (rel - 4)
                score += 2 if f in (3, 4) else 1
                if len(board.attackers(color, sq)) > len(board.attackers(not color, sq)):
                    score += 1

        for f in range(2, 6):
            for r in range(8):
                sq = chess.square(f, r)
                rel = relative_rank(sq, color)
                if 4 <= rel <= 6 and board.attackers(color, sq) & pawns:
                    score += 1

        for piece_type in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(piece_type, color):
                rel = relative_rank(sq, color)
                f = chess.square_file(sq)
                if not (4 <= rel <= 6 and 2 <= f <= 5):
                    continue
                if not (board.attackers(color, sq) & pawns):
                    continue
                if board.attackers(not color, sq) & enemy_pawns:
                    continue
                score += 4 + rel - 4
                if f in (3, 4):
                    score += 1

        return score

    if not has_anchor(stm):
        return False
    ours = space_score(stm)
    theirs = space_score(not stm)
    return bool(ours >= 11 and ours >= theirs + 7)

