MOTIF_NAME = 'Reinforced minor coalition against rook'
MOTIF_DESCRIPTION = 'The side to move has two extra minor pieces against an extra enemy rook, balanced by one enemy pawn or strengthened at equal pawns by a bishop pair or two pawn-supported minors.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    my_minors = set(board.pieces(chess.BISHOP, stm)) | set(board.pieces(chess.KNIGHT, stm))
    op_minors = set(board.pieces(chess.BISHOP, opp)) | set(board.pieces(chess.KNIGHT, opp))

    if (
        len(my_minors) != len(op_minors) + 2
        or len(board.pieces(chess.ROOK, opp)) != len(board.pieces(chess.ROOK, stm)) + 1
        or len(board.pieces(chess.QUEEN, stm)) != len(board.pieces(chess.QUEEN, opp))
    ):
        return False

    pawn_gap = len(board.pieces(chess.PAWN, opp)) - len(board.pieces(chess.PAWN, stm))
    if pawn_gap == 1:
        return True
    if pawn_gap != 0:
        return False
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        return True

    supported = 0
    for sq in my_minors:
        if board.is_pinned(stm, sq):
            continue
        if any(
            board.piece_at(a).piece_type == chess.PAWN
            for a in board.attackers(stm, sq)
        ):
            supported += 1
    return supported >= 2

