MOTIF_NAME = 'Coordinated deployment without a material edge'
MOTIF_DESCRIPTION = 'With matched non-pawn forces and at most a one-pawn deficit, the side to move has a pronounced deployment lead through active minors or a safe supported advanced rook.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    if board.is_check():
        return False

    for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
        if len(board.pieces(pt, stm)) != len(board.pieces(pt, opp)):
            return False

    pawn_gap = len(board.pieces(chess.PAWN, opp)) - len(board.pieces(chess.PAWN, stm))
    if pawn_gap not in (0, 1):
        return False

    def relrank(sq, color):
        r = chess.square_rank(sq)
        return r + 1 if color else 8 - r

    def back_minors(color):
        total = 0
        for pt in (chess.BISHOP, chess.KNIGHT):
            for sq in board.pieces(pt, color):
                if relrank(sq, color) == 1:
                    total += 1
        return total

    def useful_minors(color):
        total = 0
        for pt in (chess.BISHOP, chess.KNIGHT):
            for sq in board.pieces(pt, color):
                if relrank(sq, color) == 1:
                    continue
                for dst in board.attacks(sq):
                    f = chess.square_file(dst)
                    r = chess.square_rank(dst)
                    if 2 <= f <= 5 and 2 <= r <= 5:
                        total += 1
                        break
        return total

    our_back = back_minors(stm)
    their_back = back_minors(opp)
    our_active = useful_minors(stm)
    their_active = useful_minors(opp)
    queens_present = len(board.pieces(chess.QUEEN, stm)) > 0

    if (their_back >= our_back + 2 and our_active >= 2 and
            our_active >= their_active + 1 and
            (pawn_gap == 0 or queens_present)):
        return True

    if pawn_gap != 0 or our_back > their_back or our_active < their_active:
        return False

    enemy_rooks = board.pieces(chess.ROOK, opp)
    if not enemy_rooks:
        return False
    for sq in enemy_rooks:
        if relrank(sq, opp) != 1:
            return False

    for sq in board.pieces(chess.ROOK, stm):
        rr = relrank(sq, stm)
        f = chess.square_file(sq)
        if rr < 3 or not (2 <= f <= 5 or rr >= 6):
            continue

        supported = False
        for dsq in board.attackers(stm, sq):
            piece = board.piece_at(dsq)
            if piece and piece.piece_type != chess.KING:
                supported = True
                break
        if not supported:
            continue

        unsafe = False
        for asq in board.attackers(opp, sq):
            piece = board.piece_at(asq)
            if piece and piece.piece_type in (
                    chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.KING):
                unsafe = True
                break
        if unsafe:
            continue

        reach = 0
        target = False
        for dst in board.attacks(sq):
            piece = board.piece_at(dst)
            if piece is None or piece.color != stm:
                reach += 1
            if piece and piece.color == opp and piece.piece_type != chess.KING:
                target = True
        if reach >= 6 and target:
            return True

    return False
